/bin/bash -lc "python3 -c \"
from PIL import Image
import numpy as np
a = np.array(Image.open('first_frame.png')).astype(int)
# trace stick below head: scan region x95-135, y44-80, mark warm/tan vs background
for y in range(44,80,2):
    row=[]
    for x in range(95,135):
        r,g,b=a[y,x]
        if r>150 and g>110 and b<120 and r-b>50: row.append('#')  # bright tan/orange
        elif r-b>35 and r>110: row.append('+')
        elif r<90 and g<70: row.append('d')
        else: row.append('.')
    print(y,''.join(row))
\""
